#!/usr/bin/env python3
import json,os,signal,time,urllib.request
from pathlib import Path
home=Path.home()/'.copytolive-chat-lokal'
token=(home/'token').read_text().strip()
base='http://127.0.0.1:8765'
log=Path('_recovery_exec.log')
log.write_text('')
headers={'Content-Type':'application/json','X-CopyToLive-Token':token}
def post(path,obj):
 r=urllib.request.Request(base+path,data=json.dumps(obj).encode(),headers=headers,method='POST')
 return json.load(urllib.request.urlopen(r,timeout=5))
def get(path):
 r=urllib.request.Request(base+path,headers={'X-CopyToLive-Token':token})
 return json.load(urllib.request.urlopen(r,timeout=5))
rid='recovery-exactly-once-218'
req={'id':rid,'op':'start_process','cwd':'Chat-Lokal','argv':['python3','recovery_child.py','RECOVERY_218'],'session_id':'recovery-sideeffect-218','initial_wait_seconds':3}
print('ENQUEUE='+str(post('/v1/enqueue',req).get('ok')),flush=True)
deadline=time.time()+5
while time.time()<deadline and 'RECOVERY_218' not in log.read_text(): time.sleep(.02)
print('SIDE_EFFECT_SEEN='+str('RECOVERY_218' in log.read_text()),flush=True)
os.kill(52185,signal.SIGTERM)
up=False
for _ in range(200):
 try:
  urllib.request.urlopen(base+'/health',timeout=.3).read();up=True;break
 except Exception: time.sleep(.05)
print('DAEMON_RECOVERED='+str(up),flush=True)
result=None
for _ in range(240):
 try:
  x=get('/v1/result/'+rid)
  if x.get('status') in ('done','error'): result=x;break
 except Exception: pass
 time.sleep(.05)
lines=[x for x in log.read_text().splitlines() if x=='RECOVERY_218']
print('RESULT_OK='+str(bool(result and result.get('result',{}).get('ok'))),flush=True)
print('EXEC_COUNT='+str(len(lines)),flush=True)
print('PASS='+str(up and bool(result and result.get('result',{}).get('ok')) and len(lines)==1),flush=True)

#!/usr/bin/env python3
import sys,time
import Quartz
from AppKit import NSRunningApplication,NSPasteboard,NSStringPboardType
pid=int(sys.argv[1]);x=float(sys.argv[2]);y=float(sys.argv[3]);tag=sys.argv[4]
app=NSRunningApplication.runningApplicationWithProcessIdentifier_(pid);app.activateWithOptions_(1);time.sleep(.5)
def post(code,flags=0):
 for d in (True,False):
  e=Quartz.CGEventCreateKeyboardEvent(None,code,d);Quartz.CGEventSetFlags(e,flags);Quartz.CGEventPost(Quartz.kCGHIDEventTap,e)
def click():
 for d in (True,False):
  t=Quartz.kCGEventLeftMouseDown if d else Quartz.kCGEventLeftMouseUp;e=Quartz.CGEventCreateMouseEvent(None,t,(x,y),Quartz.kCGMouseButtonLeft);Quartz.CGEventPost(Quartz.kCGHIDEventTap,e)
 time.sleep(.25)
def key(c): post(c,Quartz.kCGEventFlagMaskCommand);time.sleep(.15)
def setclip(s):
 p=NSPasteboard.generalPasteboard();p.clearContents();p.setString_forType_(s,NSStringPboardType)
def clip(): return str(NSPasteboard.generalPasteboard().stringForType_(NSStringPboardType) or '')
click();setclip(tag+'_ONE');key(9);key(0);key(8);a=clip();key(7);setclip(tag+'_TWO');key(9);key(0);key(8);b=clip()
print('AC_PASS='+str(a==tag+'_ONE'));print('XV_PASS='+str(b==tag+'_TWO'))
